local M = class("FriendLikeLevelInfoControl",LikeOO.OOControlBase)

function M:onEnter()
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
    elseif msg == "send_gift_btn" then --一键赠送
        local params = self.m_model.m_params.sendServerData
        local sendCallBack = self.m_model.m_params.sendCallBack
        if params and sendCallBack then
            self.m_model:getNetData("giving_gifts", params, function(response)
                self:closeView()
                sendCallBack(response)
            end)
        end
    elseif msg == "giving_gifts" then
        self:closeView()
    end
end

function M:heroDetailPop(index, cell_data)

end

function M:destroy()
    M.super.destroy(self)
end


return M
